fn solve(events) {
    let balances = {}
    var rejected = 0
    for event in events {
        if event[0] == "deposit" {
            let id = event[1]
            let amount = event[2]
            if !has(id, balances) {
                balances[id] = 0
            }
            balances[id] = balances[id] + amount
        } else {
            let source = event[1]
            let target = event[2]
            let amount = event[3]
            if !has(source, balances) {
                balances[source] = 0
            }
            if !has(target, balances) {
                balances[target] = 0
            }
            if balances[source] < amount {
                rejected += 1
            } else {
                if source != target {
                    balances[source] = balances[source] - amount
                    balances[target] = balances[target] + amount
                }
            }
        }
    }
    ({ balances: balances, rejected: rejected })
}
